// Descriptions are read only from sites that serve the listing page (4zida). Nekretnine.rs and Halo return 403 → not attempted.
// Only listings that pass the filter (the ones the user reads), at most 10 per run (fewer requests to the site, fewer tokens).
const MAX = 10;
return $input.all()
  .filter(i => i.json.izvor === '4zida' && i.json.prosao_filter === true && /^https:\/\/www\.4zida\.rs\//.test(i.json.url || ''))
  .slice(0, MAX)
  .map(i => ({ json: { id: i.json.id, url: i.json.url, cena: i.json.cena ?? null, m2: i.json.m2 ?? null, sobe: i.json.sobe ?? null, naselje: i.json.naselje ?? null, opstina: i.json.opstina ?? null, oglasivac: i.json.oglasivac ?? null } }));

// 4zida (Next.js SSR): the description text is in the HTML after the "Opis oglasa" heading. Only that part is kept, without phone numbers or the agent's name.
const base = $('SelectForEnrich').item.json;
const html = String($json.html ?? '');
const i = html.indexOf('Opis oglasa');
let opis = '';
if (i >= 0) {
  opis = html.slice(i + 'Opis oglasa'.length, i + 30000)
    .replace(/<script[\s\S]*?<\/script>/g, ' ')
    .replace(/<style[\s\S]*?<\/style>/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
  const stops = ['Prikaži više', 'Prikaži manje', 'Slični oglasi', 'Cena posmatrane', 'self.__next_f'];
  const cut = Math.min(...stops.map(s => opis.indexOf(s)).filter(n => n >= 0), opis.length);
  opis = opis.slice(0, cut)
    .replace(/Agent:[\s\S]*$/, '')
    .replace(/Prikaži\s*[\d\s\/+*-]{3,}\.{0,3}/g, '')
    .replace(/\+?\d[\d\s\/-]{7,}\d/g, '[telefon]')
    .replace(/[ \t]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim()
    .slice(0, 3000);
}
return { json: { ...base, opis, http_greska: $json.error ? String($json.error.message ?? $json.error).slice(0, 200) : null } };

// Claude returns JSON → validate types and ranges. Output: only id + extracted fields; the Orchestrator merges them into the original listing.
const base = $('ExtractDescription').item.json;
const blocks = Array.isArray($json.content) ? $json.content : [];
const raw = String($json.merged_response || blocks.filter(c => c.type === 'text').map(c => c.text).join('') || '');
let p = null;
try { p = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { p = null; }
if (!p) return { json: { id: base.id, enrich_ok: false, enrich_greska: ($json.error ? String($json.error.message ?? $json.error) : 'neispravan JSON: ' + raw.slice(0, 120)).slice(0, 200) } };

const numOrNull = (v, min, max) => { const n = Number(v); return v === null || v === undefined || v === '' || !Number.isFinite(n) || n < min || n > max ? null : Math.round(n); };
const pick = (v, allowed) => allowed.includes(v) ? v : 'nepoznato';
const txt = (v, max) => (typeof v === 'string' && v.trim()) ? v.trim().slice(0, max) : null;
const sumnjiv = p.sumnjiv_oglas === true;
return { json: {
  id: base.id,
  enrich_ok: true,
  provizija: txt(p.provizija, 80),
  rezije_eur: numOrNull(p.rezije_eur, 0, 1000),
  min_period_meseci: numOrNull(p.min_period_meseci, 1, 60),
  depozit_eur: numOrNull(p.depozit_eur, 0, 5000),
  namesten: pick(p.namesten, ['da', 'polunamešten', 'ne']),
  kucni_ljubimci: pick(p.kucni_ljubimci, ['da', 'ne']),
  sumnjiv_oglas: sumnjiv,
  sumnjiv_razlog: sumnjiv ? txt(p.sumnjiv_razlog, 200) : null
} };

// Manual test only: sample 4zida listings
return [
  { json: { id: '4zida_6afb84a9bcf091b06d0db31b', izvor: '4zida', prosao_filter: true, cena: 450, m2: 30, sobe: 1, naselje: 'Kalenić', opstina: 'Vračar', oglasivac: 'agencija', url: 'https://www.4zida.rs/izdavanje-stanova/kalenic-vracar-beograd/jednosoban-stan/6afb84a9bcf091b06d0db31b' } },
  { json: { id: '4zida_6aec7072f52cf90a210c3af3', izvor: '4zida', prosao_filter: true, cena: 500, m2: 35, sobe: 1, naselje: 'Neimar', opstina: 'Vračar', oglasivac: 'agencija', url: 'https://www.4zida.rs/izdavanje-stanova/neimar-vracar-beograd/jednosoban-stan/6aec7072f52cf90a210c3af3' } },
  { json: { id: 'cityexpert_1', izvor: 'cityexpert', prosao_filter: true, url: 'https://cityexpert.rs/x' } }
];
